-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExa28a1c599028$doc_administration_of_justice_act_2073_2016__2073_566024369-administration-of-justice-act-2073-2016_pdf$CODExa28a1c599028$,$CODExbf2b3fe70429$Administration of Justice Act, 2073 (2016)$CODExbf2b3fe70429$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2073,2016,26,$CODEx75f4dc3fae58$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \n1 \n \nAdministration of Justice Act, 2073 (2016) \nDate of Authentication and Publication \n2073-05-27 BS (September 12, 2016) \nAct No. 7 of the Year 2073 (2016) \nAn Act enacted for amendment and unification of the law relating to \nadministration of justice \nPreamble: Whereas, it is expedient to make timely amendment and unification of \nprevailing law relating to administration of justice for the establishment and \nsystematic arrangement of jurisdiction of the courts so as to dispense justice fast, \ninexpensive and render easily accessible, impartial, effective and accountable with \nthe people;  \nNow, therefore, be it enacted by Legislature -Parliament in accordance with Sub -\nArticle (1) of Article 296 of Constitution of Nepal.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement : (1) This Act may be called as", "content": "“Administration of Justice Act, 2073 (2016)\".  \n(2) This Act shall come into force from such date as may be specified by the \nGovernment of Nepal by publishing a Notification in Nepal Gazette.1", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this Act,-", "content": "(a) “Court” means the Supreme Court, High Court and District Court. \n                                                           \n1 This Act has been prescribed for commencement from September 19, 2016 (the \nNotification published in Nepal Gazette on September 14, 2016) \n \nwww.lawcommission.gov.np \n2 \n \n(b) “Judge of High Court” means the Judge  of High Court and the terms \nshall also denote to the Chief Judge of the High Court. \n(c) “Prescribed” or “as prescribed” means prescribed or as prescribed in \nthe rules framed under this Act.  \n(d) “Judicial Council” means the Judicial Council as per the Article 153  \nof the Constitution. \n(e) “Constitution” means the Constitution of Nepal.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Establishment of District Court:  (1)There shall be one District Court, in", "content": "each district.  \n(2) The District Courts shall be located at the headquarters of Districts.  \nProvided however that, in case any District is being located, prior to the \ncommencement of this Act, at any place other than the District headquarters it \nshall be continuing at the same place until another arrangement is made.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "District Judges: (1) There shall be a District Judge in each District Court.", "content": "(2) Notwithstanding anything contained in Sub -Section (1), if there is more \nworkload in any District Court, the Chief Justice may, on the recommendation \nof the Judicial Council, designate the required number of additional D istrict \nJudges. \n(3) The Judicial Council shall, on the basis of workload, determine the number \nof Judges to be remained in each District Cour t subject to the total number of \npost of Judges in accordance with Sub -Section (7) and the number of District \nJudges determined so may be altered on the basis of workload.  \nwww.lawcommission.gov.np \n3 \n \n(4) If there are more than one District Judges in any Court, the senior most \nDistrict Judge shall work as a Chief of the District Court. \n(5) The Chief Justice may depute the District J udge of any District Court in \nanother District Court to work as a Judge for a certain period of time. \n(6) The District Judge, as deputed in accordanc e with Sub -Section (5), shall \nwork in the assigned District Court during the period as prescribed.  \n(7) The Government of Nepal, in recommendation of Judicial Council, shall \ndetermine the total number of post of the Judges of District Courts according \nto workload.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Establishment of High Court: (1) There shall be a High Court in the capital", "content": "of each province.  \n(2) The High Court shall be remained in the place as prescribed by the \nGovernment of Nepal in consultation with the Judicial Council until decisio n \nfor the place of the capital of the Province is made in accordance with Sub -\nArticle (2) of Article 288 of the Constitution. \n(3) The Government of Nepal  may, in consultation with the Judicial Council, \nestablish temporary bench of the High Court in other  place having under the \nterritorial jurisdiction of such Court and prescribe the location of the bench.   \n(4) While prescribing location by establishing bench pursuant to Sub -Section \n(3), territorial jurisdiction of such bench shall also be determined.  \n(5) In case there are more than one Courts of Appeal in any Province during \ncommencement of this Act, the Government of Nepal shall, in consultation \nwith the Judicial Council, determine a Court of Appeal as a High Court of the \nwww.lawcommission.gov.np \n4 \n \nProvince and next Court of Appe al shall be prescribed as next bench of the \nsame High Court. \n(6) Notwithstanding anything contains in this Section elsewhere, Government \nof Nepal may, in case the High Court is located in another place then the \ncapital of the Province, while making decisio n of the capital of the Province \npursuant to Sub -Article (2) of Article 288 of the Constitution, relocate the \nHigh Court in the capital of the Province in consultation of the Judicial \nCouncil. \n(7) The bench, established as per this Section, shall exercise jurisdiction \nequivalent to the High Court pursuant to this Act under its own territorial \njurisdiction as prescribed pursuant to Sub-Section (4).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Judges of High Court: (1) The High Court shall consist required number of", "content": "Judges subject not to exceed the total number of one hundred sixty post. \n(2)   There shall be one Chief Judge and required number of other judges as \nprescribed by the Judicial Council under the Sub -Section (1) in each High \nCourt subject not to lessen the number of ten.  \n(3) The Chief Justice shall, in recommendation of the Judicial Council, depute \nthe number of at least three Judges of High Court to work in the place of the \nbench as established pursuant to Section 5.  \n(4) The most senior Judge among the Judges deputed pursuant to Sub -Section \n(3) shall work as the Chief.  \n(5) The Government of Nepal may, in recommendation of Judicial Council, \nalter in number of Judges pursuant to Sub -Section (1) on the basis of \nworkload of the cases. \nwww.lawcommission.gov.np \n5", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "7", "title": "Jurisdiction of the District Court: (1) Except as otherwise provided in the", "content": "prevailing law, the District Court shall hav e powers to try and settle, in \noriginal jurisdiction, all the cases within the jurisdiction of its own district and \nin the cases as ordered by the High Cour t for trial pursuant to Sub -Article (2) \nof Article 145 of the Constitution.  \n(2) The District Court s hall have powers to issue order  of habeas corpus, for \nthe enforcement of legal rights of any one under its territorial jurisdiction  of \nthe District, if anyone keeps any person under unlawful detention.  \n(3) The District Court shall have powers to issue orders of injunction for the \nenforcement of legal rights of any person infringed or there is reasonable \ndoubt of infringing by anybody or authority under the territorial jurisdiction of \nthe district.  \n(4) Except as otherwise provided in the prevailing law, the District Court shall \nhave powers to hear appeals against decision or final order made by the quasi -\njudicial body or authority under the territorial jurisdiction of the District in \naccordance with federal law and against the decision or final order made by \njudicial body of local level constituted in accordance with the provincial law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Jurisdiction of the High Court: (1) The High Court shall have the power to", "content": "issue necessary and appropriate order by hearing over the application filed in \naccordance with Sub-Article (1) of Article 144 of the Constitution.  \n(2) The High Court shall have the power to try, under its original \njurisdiction, and settle the following cases:                                 \nwww.lawcommission.gov.np \n6 \n \n(a) The case s which the High Court is empowered by federal law to try \nand settle under its original jurisdiction,  \n(b) The cases taken from the sub-ordinate court in accordance wi th Sub-\nArticle (1) of Article 145 of the Constitution. \n(3) The High Court shall have power to make decision by hearing appeal in \nfollowing cases; \n(a)  Cases tried and settled by District Court under its original jurisdiction \npursuant to Sub-Section (1) of Section 7. \n(b) Cases in whic h full or partial reversal of decisions made by judicial, \nquasi-judicial body or authority has been made by the District Court \nmade on appeal against such decisions.  \n(c) Cases, in which decision has been made by the District Court over the \nappeal against the decisions, involving the dispute relating to public \nproperty, cases in which punishment of imprisonment or the fine of \nthe sum of more than one hundred thousand has been imposed or \nhaving the claimed amount of the sum more than five hundred \nthousand. \n(d) Except as otherwise provided in the federal law, cases tried and \nsettled under original jurisdiction by any judicial body under its \nterritorial jurisdiction.  \n(4)  The High Court shall have the power to review over the reference \njudgments (Sadhak) according to the federal law. \nwww.lawcommission.gov.np \n7", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Power of the Supreme Court to hear Appeal: (1) The Supreme Court shall", "content": "have the power to hear appeal in following cases; \n(a) Cases tried and settled by High Court under its original jurisdiction \npursuant to Sub-Section (2) of Section 8, \n(b) Cases in which punishment of imprisonment for Ten years or more \nhas been imposed;  \n(c) Cases, in which full or partial reversal in the decisions made by trial \ncourt, body or authority has been made by the High Court in which \npunishment of imprisonme nt of more than three years or the fine of \nthe sum of more than five hundred thousand has been imposed or \nhaving the claimed amount of the sum of more than two million five \nhundred thousand, and \n(d) Other cases, in which appeal to be filed before the Supreme C ourt in \naccordance with the federal law. \n(2) The Supreme Court shall have the power to hear an appeal on reference \ncases submitted before the Supreme Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Provision on Reference of the Cases: (1) In case where reference of the case", "content": "is required under the prevailing federal law, reference has to be made to the \ncourt hearing appeal.  \n (2) Notwithstanding anything contains in Sub -Section (1), such reference to \nthe Supreme Court shall be made only if the High Court has imposed  the \npunishment of life imprisonment.  \n(3)  In cases where an appeal  is filed in the case of which reference has been \nmade pursuant t o Sub-section (1) or (2), such a case shall be adjudicated by \nway of appeal, and where in the same case some make appeal and some don’t \nwww.lawcommission.gov.np \n8 \n \nmake, then the case shall be adjudicated and decided upon, in resp ect of the \nnon-appellant also, by way of the process of reference.  \n(4)If non-appealing party or any other concerned person makes a petition with \npleas similar to an appeal in the case to be heard by way of reference process, \nthe court hearing the appeal shall have to settle the case, taking also into \naccount of such petition.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Provision on Review: (1) The decision or final order made by any Court shall", "content": "not be reviewed by the same Court. \n(2) Notwithstanding anything contains in Sub -Section (1) t he Supreme Court \nmay review its judgment or final order in the following circumstance:  \n(a) If it appears that the concerned party has come to know any fact l ikely \nto material ly affect the justice done in the case only after the \nsettlement of the case, or  \n(b) If it appears that th e decision is contrary to the precedent or leg al \nprinciple enunciated by the Supreme Court.  \n(3) The Supreme Court shall not review its judgment or f inal order in the \nfollowing circumstance:  \n(a) If the judgment or final order has already been reviewed earlier,  \n(b) If the Judgment or final order has been made by Larger Full Bench, \n(c) If the decision has been made by Constitutional Bench, \n(d) If the case has already been settled by way of revision pursuant to the \nprevailing law prior to the commencement of this Act, or \nwww.lawcommission.gov.np \n9 \n \n(e) If the judgment of the High Court has been confirmed or the approval \nhas not been granted for revision in the case reviewed pursuant to \nSection 12. \n(4) A petition for review shall be made within Sixty days of the date of \ncertification by affixing signature in the judgment or final order by the Justice \nof the Supreme Court. \n(5) Order shall be made by the Justices other than the Justices made the earlier \njudgment over the application filed pursuant to Sub -Section (4) in the issues \nthat whether to grant approval for review or not. \n(6) If the approval to review the case has been  granted pursuant to Sub -\nSection (5), hearing over the application shall be made by the bench of the \nJustices other than the Justices, who have made the earlier judgment and the \nJustices, who have given approval to review the case.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Provision on Revision of the Case : (1) The Supre me Court may, in the", "content": "following circumstances, revise the judgment or final order made by the High \nCourt in the cases which are  not appealable to the Supreme Court pursuant to \nthis Act or the prevailing laws:  \n(a) If there is  serious Constitutional or legal error in the judgment or \nfinal order made by the High Court, \n(b) If the principle o r precedent established by the Supreme Court has \nnot been followed or has been applied with false interpretation,  \n(c) If any public pro perty has been misappropriated or loss caused i n \nsuch prop erty due to lack of proper evaluatio n of the evidence \ncontained in the case file in a ca se involving dispute vis -à-vis \ngovernment or public property; or  \nwww.lawcommission.gov.np \n10 \n \n(d) If the justice is subs tantially affected due to lack of proper \nrepresentation of a child, woman, disabled or mentally retarded \nperson or the person crossed the age of seventy five years.  \n(2) Notwithstanding anything contains in Sub -Section (1), revision shall not \nbe made in following cases:- \n(a) A case once heard and adjudicated by the Supreme Court, \n(b) A case a djudicated by the High Court by hearing appeal in \naccordance with Part (B) of Sub-Section (3) of Section 8. \n(3) A petition for revision may be filled within Forty Five days from the date \nof decision by the High Court through the High Court having made such  \ndecision or in the Supreme Court.  \n(4) The details and documents as prescribed shall be enclosed with the \npetition to be filed in accordance with Sub-Section (3). \n(5) The decision, whether to grant revision or not, shall be made by the \nDivision Bench by h earing over the petition filed in accordance with Sub -\nSection (3) that whether the situation of Sub -Section (1) is being existed or \nnot. \n(6) If the approval has been is granted pursuant to Sub -Section (5), hearing \nover the application shall be made by the bench of the Justices other than the \nJustices, who have given approval for revision and the Justices, who have \nmade the earlier judgment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Compromise can be Made: Compromise can be made on a petition filed and", "content": "action initiated in the petition as referred to Section 11 or 12. \nwww.lawcommission.gov.np \n11", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "The powers of the Court hearing Appeal and hearing Reference cases: (1)", "content": "Subject to this Act and the prevailing laws, the powers of the cou rt hearing \nappeal and the court hearing reference cases shall be as follows:  \n(a) To confirm or to alter, wholly or partly, the decision of any \nsubordinate court, body or authority,  \n(b) To exercise the powers of ren dering judgment or final order similar \nto any subordinate court, body or authority,  \n(c) If the subordinate court, body or authority has fa iled to examine any \nevidence relevant t o the question of adjudication in the case, to \nexamine such evidence by itself or to send temporarily the file of the \ncase back to  the subordinate court, body or authority in order to \nexamine such evidence  by maintaining the record of the case in the \nCourt as it is, \n(d) If the subordinate court, body or authority has to give its decision on \nsome issues and failed to give its decision in other issues involved in \nthe case, to send back the case file of the case, within a period \nprescribed for completion thereof, to the subordinate court, body or \nauthority for its decision on the remaining questions.  \n(2) N otwithstanding anything contains  in Part (D) of Sub -Section (1), the \nDistrict Court and the High Court may give decision by entering into the \nissues missed by the subordinate court, body or authority over  the case filed \nbefore the court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Petition may be filed against Provisional/Interim Order: (1)", "content": "Notwithstanding anything contained in the prevailing laws, a petition may be \nfiled by the dissatisfied party at the court hearing appeal, of only one level \nwww.lawcommission.gov.np \n12 \n \nhigher, against an order of a court, body or authori ty requiring the defendant \nto make presence on the appointed dates or furnish guarantee or be kept under \ndetention for trial or against any provisional/interim order made in the course \nof proceedings of the case.  \n(2) Notwithstanding anything contained in Sub -Section (1) nothing contained \nin this Section shall be deemed to bar the making of a petition to the Supreme \nCourt on the question of legal error or procedural irregularity, against an order \nrequiring the defen dant to make presence on the appointed dates or furnish \nguarantee or be kept under detention for trial, in a case involving punishment \nof imprisonment for a term of Ten years or more.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Exercise of J urisdiction of the C ourt: (1)The jurisdiction of the District", "content": "Court shall be exercised by the Bench of the District Judge.  \n(2) The Bench of a single judge or a Division Bench of judges shall, in the \nmanner as prescribed, exercise the jurisdiction of the High Court.  \n(3) If consensus couldn’t be made between  Judges, while making decision of \nthe case to be heard by Division Bench in accordance with Sub -Section (2), \nthe case shall be submitted before the third Judge with the opinion of both \nJudges. If the majority couldn’t be made even while submitting before t he \nthird Judge, the case file shall be sent to the Supreme Court for making \ndecision with the opinion of all Judges by giving date to attend the Court to \nthe parties of the case presented in appointed date. \n(4) If any proceeding, other than the act of rendering judgment or final order, \nis carried out by a single judge in any case , which is required to be heard by  \ntwo or more judges according to the law, no such proceeding shall be deemed \nto be beyond jurisdiction nor shall it be void.  \nwww.lawcommission.gov.np \n13", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Action to be taken in Contempt of C ourt: (1) The Supreme Court may", "content": "initiate proceedings against the contempt of court, if anyone makes obstacle in \njudicial performance or dishonor the order or judgment of its own or the High \nCourt or District Court. \n(2) The High Court may initiate proceedings against the contempt of court, if \nanyone makes obstacle in judicial performance or dishonor the order or \njudgment of its own or District Court or judicial body sub-ordinate to it. \n(3) The District Court may initiate proceedings against the contempt of court, \nif anyone makes obstacle in judicial performance or dishonor the order or \njudgment of its own or judicial body sub-ordinate to it. \n(4) If the act of contempt of court is found to be pr oved, while proceeding \naction in accordance with Sub -Section (1), (2) or (3), the concerned  Court \nmay punish the offender with imprisonment for upto one year and a fine of up \nto Ten Thousand Rupees or with both or issue appropriate order. \n(5) The accused, against whom the case of contempt of court is initiated, may \napologize before the court at any situation before delivering judgment by the \nCourt. The Court may, i f the court is satisfied with such apology, stop the \nproceeding of the case. \n(6) Notwithstanding anything contained in this Section elsewhere, if the \nperson, proved as an offender of contempt of court, apologizes to the \nsatisfaction of the Court, the Court may not execute the punishment, reduce or \nchange in punishment or issue an order  with effect of non -execution of the \nsentence, if the conditions are complied with by the accused.  \nwww.lawcommission.gov.np \n14", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Finality of decisions of the Court : (1) Except as otherwise provided in this", "content": "Act or in the prevailing laws, any decision made by a Court, body or authority \nin a case shall be final and binding to all the parties to the case.  \n(2) Except as otherwise provided in this Act or in the prevailing laws, any \ncase once decided by the Court, body or authority shall not be retried by the \nsame Court, body or, author ity, nor shall any amendment be made to such \ndecision or order affecting the judgment.   \n(3) Notwithstanding anything contained in Sub -Section (2), the minor error \nmade in typi ng or writing can be corrected by executing a separate memo  \nsubject not to make substantial difference in the judgment.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "19", "title": "Power to withdrawal and settlement of the case : The Supreme Court shall", "content": "have the power to withdraw and hear the case having under consideration in \nHigh Court in the situation as specified in Sub-Article (1) of Article 134 of the \nConstitution.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Power to Issue Order to transfer the case : (1) The Sup reme Court may, in", "content": "the situation as specified in Sub -Article (2) of Article 134 of the Constitution , \nissue order to hear the case having under consideration in one High Court by \ntransferring it into another High Court. \n(2) The High Court may, in the situat ion as specified in Sub -Article (2) of \nArticle 145 of the Constitution, issue order to hear the case having under \nconsideration in one District Court by transferring it into another District \nCourt. \nwww.lawcommission.gov.np \n15 \n \n(3) The decision, whether or not the situation to transfer  the case pursuant to \nSub-Section (1) or (2) is existed, shall be made in accordance with  the \ninformation acquired from inspection report of concerned court, application of \nconcerned parties of the case or any other means.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "21", "title": "Provision on Inspection: (1) Each Court hearing appeal shall, at least once a", "content": "year, inspect its subordinate courts, judicial or quasi -judicial body or the \nauthorities by deputing its own judge.  \n(2) While carrying out inspection in accordance with Sub -Section (1), the act \nof inspection shall be done to the cases pending with the concerned Court, \nbody or authority and the cases heard and settled by such a Court, body or \nauthority.  \n(3) While carryi ng out inspection in accordance with Sub -Section (2), in -\nparticular case-files relating to following cases shall be inspected. \n(a) Cases wherein a person is detained for trial,  \n(b) Some cases, out of the cases being settled finally in absence of appeal,  \n(c) Cases where any children, women or disabled , suffered by mental \nillness or the person crossed the age of seventy five years are involved \nas a party of the case, \n(d) Cases where any question of public concern or interest is involved \ntherein.  \n(e) Case, where any incapable person is involved as the party of the case \nwww.lawcommission.gov.np \n16 \n \n(4) While carrying out inspection in according to this Section, the act of \ninspection shall be done in following aspects: \n (a) Whether or not the execution of judgments has been performed in t he \ntime,  \n(b) Whether or not the orders and directives issued by  superior Courts \nhave been carried out, and  \n(c) Whether or not the proceeding in the sub judice  cases are being \nperformed satisfactorily.  \n(5) While carrying out inspection or enquiry in acco rdance with Sub -Section \n(2), (3) or (4), in case it is found that any act supposed to be performed has not \nbeen performed and the act supposed to be not performed has been performed, \nthe inspecting Judge shall issue order on the spot to do as per the law. \n  Provided however that if the order , issued to the defendant to make \npresence on the appointed dates or furnish guarantee or be kept under \ndetention for trial (Thunchhek Aadesh) in criminal case , where the \nGovernment of Nepal is the party , is required to be quashed, report shall be \ngiven to the court hearing appeal of the inspected court and send to concerned \ncourt to do as per the order of said court. \n(6) The inspecting judge may also make inquiries with the employees of the \nCourt, body or authority being inspected with the parties to the cases present \nin the Court , body  or authority, the legal practitioners and other related \npersons with respect of the acts and actions of the concerned Court, body or \nauthority and ask for their suggestions and comments thereon. \nwww.lawcommission.gov.np \n17 \n \n(7)The inspecting judge shall, by preparing report of inspection and evaluation \nafter the completion of the act of inspection, send an inspection report  to the \nSupreme Court , the concerned court hearing appeal  and the Secretariat of \nJudicial Council, where the insp ection of a Court has been made. The report \nshall be submitted to the Supreme Court, the court hearing appeal,  concerned \nMinistry and concerned body of state government having authority to take \naction, where the inspection of judicial or qu asi-judicial body or authority has \nbeen made.    \n(8) The Judicial Council or the body receiving such report shall, after \nreceiving inspection and evaluation report submitted as per the Sub -Section \n(7), take action in the issues as mentioned in the report b y carrying out \nnecessary enquiry as quick as possible and such action shall also be a criterion \nof evaluation for career development of concerned official.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Casual inspection: (1) The Supreme Court may , by making deputation of the", "content": "Judge of own Court,  perform a casual inspection of any High Court and \nDistrict Court, the High Court may, by making deputation of the Judge of own \nCourt, perform such inspection of any subordinate District Court or office of \nthe judicial or quasi -judicial body or authority and the District Court may, by \nmaking deputation of the Judge of own Court,  perform such inspection of \njudicial activities of body or authority being heard the appeal by such District \nCourt.  \n(2) The Judge carried out the act of inspection in accordance with Sub-Section \n(1) shall submit the inspection report before the Supreme Court, the Judicial \nCouncil and concerned High Court by depicting the fact found in the course of \ninspection and in respect of the inspection of the office of the quasi -judicial \nwww.lawcommission.gov.np \n18 \n \nbody o r authority, such report shall also be submitted before concerned \nMinistry and concerned body of state government having authority to take \naction. \n (3) The Supreme Court may depute any justice of the Supreme Court or any \nJudge of the High Court or District Court to perform a casual inspection of the \nactivities of any-body or authority with respected to the case. \n(4) The Justice or the Judge deputed to perform the act of inspection in \naccordance with Sub -Section (3) shall, after completion of the act of \ninspection, prepare the report of inspection and evaluation and submit before \nthe Supreme Court and concerned Ministry and concerned body of state \ngovernment having authority to take action.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "To Write for  action: (1) If any action or legal proceeding is required to be", "content": "taken against any judge or officer from the report of inspection conducted \nunder this Act due to his/her mistaken or failure to perform any act required to \nbe done in the course of hearing case , the Supreme Court shall write thereof \nwith reason and base of such action to the Judicial Council or the concerned \nMinistry.  \n (2) Notwithstanding anything contains in Sub-Section (1), the Judicial Council \nor concerned body may , on the basis of inspection report submitted before it, \ninitiate action or  legal proceeding against concerned Judge or officer by  \ngiving reason and base of such action.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Enquiry can be initiated : (1) The Chief Justice may, If she/he believes that", "content": "any employee working in the Court  has performed any irregularity in the \nfunction to be performed from the Court or received any complaint or \nwww.lawcommission.gov.np \n19 \n \ninformation in this regard, depute to any gazette officer working in the Court \nfor investigation. \n (2) The officer, deputed for investigation in acc ordance with Sub-Section (1), \nshall submit report before the Chief Justice with his/her opinion by \nmentioning details of the activities occurred with this regard within seven \ndays from the date of assign work. \n (3) If any irregularity of any employee has b een found by the report received \nin accordance with Sub -Section (2), it shall be written to concerned body or \nauthority to initiate necessary action.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "25", "title": "Provision on Camera Court: (1) The case to be heard from Camera Court as", "content": "per the prevailing laws shall be heard in Camera Court.  \n(2) Other provision relating to Camera Court shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Special Provision relating to hearing of the petition of Habeas Corpus: (1)", "content": "If the Court is to remain closed for Three or more days, a judge as hereunder \nshall be designed to accept and hear petition of habeas corpus during the \nperiod of closure:- \n(a) With regard to Kathmandu Valley, the Justice of  Supreme Court \nas deputed by the Chief Justice, \n(b) With regard to the District locating High Court and District Court, \nthe Judge of concerned High Court deputed  by  the Chief Judge of \nthe High Court, \nClarification: For the purpose of this part “High Court”  shall also \nmeans the location (Mukam) of High Court.  \nwww.lawcommission.gov.np \n20 \n \n(c) In other place excluding Part (a) and (b), where District Court is \nlocated, the Judge of concerned District Court and if there are more \nthan one District Judges in such District, the District Judge \nassigned by the District Judge wo rking as a Chief of the District \nCourt.   \n(2) Notwithstanding anything contains in this Act or other prevailing laws, the \nJudge assigned in accordance with Sub -Section (1) may issue appropriate \norder by hearing over the petition filed before concerned Cour t during the \nperiod such closure the Court and concerned authority shall implement such \norder even in the time of holiday, \n(3) The place to filing petition in accordance with this Section and hearing \naccordingly shall be as determined by the Judge as presc ribed in accordance \nwith Sub-Section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "To Issue Search Warrant : (1) The Court may, in order to make assure the", "content": "reality of fact, issue search warrant in following situation in the course of \nproceeding over the petition of habeas-corpus:- \n(a) If there is any reason to make assure to the Court that the detainee \nhas been detaining in inhuman manner or illegal torture has been \ngiven to him/her, or  \n(b) If the petitioner shows any reason to make assurance to the Court that \nit is necessary to issue sear ch warrant due to possibility of transfer of \nthe detainee in another place with intention to elude the order of the \nCourt, or \n(c) If the Court considers that it is necessary or appropriate to issue order \nof search warrant due to any other similar reasons. \nwww.lawcommission.gov.np \n21 \n \n(2) The Court may, while issuing search warrant in accordance with Sub -\nSection (1), issue an order in the name of its subordinate officer or staff or any \nincumbent officer or employee of the Government of Nepal to produce the \ndetainee before the court by carrying out search in any place where detainee is \nsaid to be detained or any other suspicious place or places where the detainee \nis kept under imprisonment. The Court may, if it deems necessary or \nappropriate while issuing such order, constitute a search team comprising said \nemployee and person representing the petitioner including office bearer of \nlocal body and give the power to the team carry out the act of searching. \n(3) The person or team , getting order for searching in accordance with Sub -\nSection (2), shall search the detainee as per the direction of the Court and if \nthe detainee is identified, the assigned person or team shall submit the report \nwith the detainee before the court immediately. \n(4) If there is reasonable ground to believe that the officer or  employee, \nauthorized to carry out the act of searching in accordance with Sub -Section \n(2), couldn’t know the detainee, the Court may issue order to any other person \nto provide support in the act of execution of the search warrant. \n(5) If the Court deems n ecessary to identify the clear fact with regard to the \ndetention by the Court itself or any other sub -ordinate court in order, it may \nexamine the evidence to identify clear fact with regard to the petition of \nhabeas corpus.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Acts to be performed by judge himself or herself : (1) The judge shall", "content": "himself or herself perform the act of making decision or issuing order and \nrecording the statement of parties or witness to the case.  \nwww.lawcommission.gov.np \n22 \n \n Provided however that there shall be no any obstruction to the  Judge to write \nor offer him or herself and may get the document of judgment or order scribed \nor typed by an employee of the Court and the judge shall, during the recording \nof statement of parties or witness, ask the questions by him or herself, and \nmay get such questions and the answers scribed by an employee of the Court. \n(2) Notwithstanding anything contained in Sub-section (1), during the absence \nof the judge, the Shrestedar (Registrar) of the District Court may record the \nstatement of parties or witness and issu e order relating to detention of the \naccused pending the trial, or release him or her on bail or on recognizance to \nappear on the appointed date. \n(3) The Judge shall, upon his or her resumption of duty in the Court, review \nthe orders issued pursuant to Sub -section (1), and, if such order is found to be \nagainst the due process of law , shall rectify them to accord with the \nprocedures of law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Deemed to be established the District Courts and Posting in the Post of", "content": "District Judge (1) The District Courts existing at the time of commencement \nof this Act shall be deemed to have been established under this Act. \n(2) The District Judges working in the District Courts existing at the time of \ncommencement of this Act shall be deemed to have been ipso -facto posting in \nthe same District Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Dissolution of Courts of Appeal: The Courts of Appeal existed at the time of", "content": "commencement of this Act shall be ipso -facto dissolved after commencement \nof this Act. \nwww.lawcommission.gov.np \n23", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Transfer of cases:  (1) Cases, appeal, petitions  and reports filed and pending", "content": "in the District Courts at the time of commencement of this Act shall be ipso-\nfacto transferred to the District Courts established after the commencement of \nthis Act.  \n(2) If the territory of any District has been divided into two P rovinces in \naccordance with the Constitution at the time of commencement of this Act, \ncases to be tried and settled or hearing appeal by the District Court pursuant to \nthis Act and prevailing laws under such District shall be heard by the District \nCourt as  prescribed by Government of Nepal in consultation with Judicial \nCouncil by issuing notice in Nepal Gazette until confirmation of border of \nsuch District. An appeal over the judgment of such District Cou rt or the \ndecision made by the body or authority, as per the prevailing laws, shall lie in \nHigh Court to hearing the appeal of said District Court. \n(3) Notwithstanding anything contains in Sub -Section (1), if territory of any \nDistrict is changed and merged in other District in accordan ce with the \nConstitution, cases, petitions and reports pending at that District Court  shall \nbe transferred in the District Court as prescribed by Government of Nepal in \nconsultation with Judicial Council by issuing notice in Nepal Gazette. \n(4) Cases, appea l, petitions and reports filed and pending in the Court of \nAppeal at the time of commencement of this Act shall be transferred to the \nHigh Courts as prescribed by Government of Nepal in consultation with \nJudicial Council by issuing notice in Nepal Gazette. \n(5)  If jurisdiction of any High Court or District Court is changed due to \nchanging border of any Province by merging the Province into any other \nProvince after commencement of this Act, cases, petitions and reports pending \nwww.lawcommission.gov.np \n24 \n \nat that High Court or District Court shall be transferred in the High Court or \nDistrict Court as prescribed by Government of Nepal in consultation with \nJudicial Council by issuing notice in Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "To lie Appeal: If any judgment, decision or final order made by judicial, quasi-", "content": "judicial body or authority during the commencement of this Act was \nappealable before the Court of Appeal as per the law of enforced in that time, \nsuch appeal shall, after the commencement of this Act, lie in the High Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Petition or Appeal over t he Decision of Court of Appeal : (1) If a petition", "content": "for leave of appeal may be made in the Supreme Court, against the judgment \nor final order of the Court of Appeal, made prior to the commencement of this \nAct, such a petition for leave of appeal may be filed after the commencement \nof this Act in the Supreme Court according to the prevailing laws.  \n(2) If a petition for revision may be made in the Supreme Court, again st the \njudgment or final order of the Court of Appeal, made prior to the \ncommencement of this Act, such a petition may be filed after the \ncommencement of this Act in the Supreme Court according to the prevailing \nlaws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Files, documents or details on cases to be sent: (1) If an order, for the sake of", "content": "evidence in a case, is issued by a Court , judicial or quasi -judicial body or \nauthority to send or submit to it any file, document or any fact relating thereto \nor an explanation or response is demanded, the o ffice so addressed shall \ncomply with such order within the reasonable time. \n(2) If, any office failed to send case file, document or reply as demanded by \nthe Court in accordance with Sub -Section (1) within the time limit as \nprescribed by the prevailing law s or as specified by the Court , the Court may \nwww.lawcommission.gov.np \n25 \n \nimpose punishment of a fine of One Thousand Rupees to Ten Thousand  \nRupees for each count thereof, on the chief or employee of the concerned \noffice.  \n(3) Notwithstanding anything contains in Sub -Section (2), after the order of \npunishment is issued, if the chief or employee of the concerned office makes \npetition that such punishment should not have been imposed, stating the \nreasons for being unable to comply with the order, and on being satisfied with \nsuch reasons, the Court may reduce the amount of fine or cancel the order of \nthe punishment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Powers to issue direction : (1) The Chief Justice may, f or the efficient", "content": "management and performance of the judicial administration, issue required \ndirection to any subordinate Court, body or authority in written form.  \n(2) The Chief Judge of concerned High Court may, for the efficient \nmanagement and performance of the judicial administration, issue required \ndirection to any subordinate District Court, body or authority in written form. \n(3) The subordinate Court, body or authority shall have the duty to abide by \nsuch direction issued pursuant to Sub-Section (1) or (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Powers to frame Rules : (1) The Supreme Court may frame necessary Rules", "content": "in order to implement of this Act. Such rules shall come into force after their \npublication in the Nepal Gazette.  \n(2) Without any prejudice to the generality of the powers conferred by Sub -\nsection (1), Rules may be framed  on the following matters  in addition to the \nmatters as mentioned in this Act elsewhere:  \nwww.lawcommission.gov.np \n26 \n \n(a) Provisions relating to the exercise of jurisdiction of the High Court by \nthe Bench consisting of one or more judges, \n(b) Procedures for filing complaint, appeal or petition in the Court other \nthan the Supreme Court, fees relating thereto and other matters \nrelating to procedures in the cases, \n(c) Provision on granting approval to review the case, \n(d) Conditions and situations for transferring or extradite of cases from \none Court to other Court, \n(e) Methods of collecting rec ords and statistics relating to the \nperformance of the judges of the Courts.  \n (f) Other matters relating to the proceedings  of the administration of \njustice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Conversion: Conversion has been made by mentioning following", "content": "terminologies in place of following terminologies remained in prevailing law. \n(a) “High Court” in place of the term of “Court of Appeal”, \n(b) “Judge of High Court” in place of the term of “Judge of Court of \nAppeal”", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Repeal and saving: (1) Following Acts are hereby repealed.", "content": "(a) Administration of Justice Act, 2048 (1991), \n(b) Supreme Court Act, 2048 (1991) \n(2) Any acts done and actions taken under the Acts repealed pursuant to Sub -\nsection (1) shall be deemed to have been done and taken under this Act.", "children": []}]}]$CODEx75f4dc3fae58$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
